CREATE FUNCTION [purchase].[PurchaseOutstanding](@PurchaseInvoiceId UNIQUEIDENTIFIER) RETURNS DECIMAL(18,2) AS BEGIN DECLARE @v DECIMAL(18,2);SELECT @v=CASE WHEN i.GrandTotal-i.PaidAmount-ISNULL(r.Amount,0)<0 THEN 0 ELSE i.GrandTotal-i.PaidAmount-ISNULL(r.Amount,0)END FROM purchase.PurchaseInvoices i OUTER APPLY(SELECT SUM(AdjustmentAmount)Amount FROM purchase.PurchaseReturns WHERE PurchaseInvoiceId=i.PurchaseInvoiceId)r WHERE i.PurchaseInvoiceId=@PurchaseInvoiceId;RETURN ISNULL(@v,0);END;
